"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "@/lib/utils"

// Neon Vault Slider: a recessed dark track with the hero magenta material
// (gradient + sheen + rim + glow, same as the primary Button) on the filled
// range; the thumb is a raised puck with a magenta rim.

const Slider = React.forwardRef<HTMLDivElement, SliderPrimitive.Root.Props>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max]

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full", className)}
        {...props}
      >
        <SliderPrimitive.Control className="relative flex w-full touch-none select-none items-center">
          <SliderPrimitive.Track data-slot="slider-track" className="relative h-2 w-full grow rounded-full border border-border bg-input [box-shadow:var(--shadow-inset)]">
            <SliderPrimitive.Indicator data-slot="slider-range" className="absolute h-full rounded-full bg-primary [background-image:var(--gradient-primary)] [box-shadow:var(--shadow-button)]" />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb
              data-slot="slider-thumb" key={index}
              className={cn(
                "block h-5 w-5 rounded-full bg-foreground",
                "[box-shadow:0_0_0_0.0625rem_oklch(0.55_0.21_350/0.6),0_0.0625rem_0.1875rem_oklch(0_0_0/0.45),0_0.125rem_0.5rem_oklch(0.65_0.24_350/0.3)]",
                "transition-transform duration-fast hover:scale-105",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                "data-disabled:pointer-events-none data-disabled:opacity-50"
              )}
            />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    )
  }
)
Slider.displayName = "Slider"

export { Slider }
